#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# This wizard never runs anything on the server and never stores a value
# locally. Dokku config is the only copy of every setting: it prints the
# commands to paste into a shell on the server, and the secrets are generated
# there. See docs/deploy.md.

# on_server prints the commands to paste into a shell on the Dokku server.
on_server() {
  printf '\n  %sPaste on the server:%s\n\n' "$DIM" "$RESET"
  local line
  for line in "$@"; do printf '    %s%s%s\n' "$BOLD" "$line" "$RESET"; done
  printf '\n'
}

# on_laptop prints the commands to run in this repo on your machine.
on_laptop() {
  printf '\n  %sRun here, in the repo:%s\n\n' "$DIM" "$RESET"
  local line
  for line in "$@"; do printf '    %s%s%s\n' "$BOLD" "$line" "$RESET"; done
  printf '\n'
}

# ask_until KEY "Prompt" PATTERN repeats ask until the answer matches PATTERN.
ask_until() {
  while :; do
    ask "$1" "$2"
    [[ "${!1}" =~ $3 ]] && return 0
    warn "that doesn't look right; try again"
  done
}

run_wizard() {

TOTAL_STAGES=13

banner "webedit: first production deploy"

stage "Where it goes"
say "Three names this wizard puts into the commands it prints. Nothing is saved."
ask APP "Dokku app name (Enter for webedit):"
APP="${APP:-webedit}"
ask_until DOMAIN "Domain the editor is served on (DNS already points at the VPS), e.g. edit.example.com:" '^[A-Za-z0-9.-]+\.[A-Za-z]{2,}$'
ask_until DOKKU_HOST "SSH host of the Dokku server (for git push), e.g. vps.example.com:" '^[A-Za-z0-9.-]+$'
BASE_URL="https://$DOMAIN"
REDIRECT_URI="$BASE_URL/auth/callback"
note "Base URL $BASE_URL · redirect URI $REDIRECT_URI"
pause

stage "Dropbox: create the app"
say "Register a Dropbox app that can only reach its own folder (ADR 0003)."
open_url "https://www.dropbox.com/developers/apps/create"
step "1. Choose an API: Scoped access."
step "2. Type of access: App folder (not Full Dropbox)."
step "3. Name your app: anything unique, e.g. webedit-<yourname>."
step "Click Create app. You land on the app's Settings tab: keep it open."
pause "Created? Press Enter"

stage "Dropbox: permissions"
say "The app asks for exactly four scopes; Dropbox refuses sign-in if any is missing."
step "Open the Permissions tab and tick these four (and nothing else):"
note "    account_info.read      (ticked by default)"
note "    files.metadata.read"
note "    files.content.read"
note "    files.content.write"
step "Click Submit at the bottom of the page."
warn "If you change scopes after signing in, sign in again to get them."
pause "Submitted? Press Enter"

stage "Dropbox: settings"
step "Back on the Settings tab:"
step "App folder name: set it to webedit, so the folder is /Apps/webedit/."
step "OAuth 2 → Redirect URIs: add exactly this, then click Add:"
note "    $REDIRECT_URI"
step "Copy the App key (not secret: it appears in every sign-in URL)."
ask_until DROPBOX_APP_KEY "Paste the App key:" '^[a-z0-9]+$'
note "Leave the App secret where it is: you paste it straight into the server in stage 8."
pause

stage "Your Dropbox account ID"
say "Only this account may sign in (ADR 0002). It looks like dbid:AAB..."
open_url "https://dropbox.github.io/dropbox-api-v2-explorer/#users_get_current_account"
step "Click Get Token and allow access, signed in as the Dropbox account you'll edit with."
step "Click Submit Call; copy the value of \"account_id\" from the response."
note "Fallback: skip this, deploy, sign in once; 'dokku logs $APP' then shows the refused account_id."
ask_until WEBEDIT_OWNER_ACCOUNT_ID "Paste the account_id:" '^dbid:[A-Za-z0-9_-]+$'

stage "Dokku: app and domain"
on_server \
  "dokku apps:exists $APP 2>/dev/null || dokku apps:create $APP" \
  "dokku domains:set $APP $DOMAIN" \
  "dokku ports:set $APP http:80:5000"
note "Without ports:set, Dokku copies the Dockerfile's EXPOSE 5000 and nginx listens on :5000,"
note "so the plain domain shows nginx's default page. letsencrypt:enable later adds https:443:5000."
pause "Done? Press Enter"

stage "Dokku: configuration"
say "Public values first. --no-restart: the app isn't deployed yet."
on_server \
  "dokku config:set --no-restart $APP \\" \
  "  WEBEDIT_DROPBOX_APP_KEY=$DROPBOX_APP_KEY \\" \
  "  WEBEDIT_OWNER_ACCOUNT_ID=$WEBEDIT_OWNER_ACCOUNT_ID \\" \
  "  WEBEDIT_BASE_URL=$BASE_URL \\" \
  "  WEBEDIT_DATA_DIR=/data"
pause "Done? Press Enter"

stage "Dokku: secrets"
say "Secrets are made on the server and never printed. Each is set only if missing,"
say "so rerunning never signs you out or invalidates the stored token."
on_server \
  "[ -n \"\$(dokku config:get $APP WEBEDIT_SESSION_SECRET)\" ] || dokku config:set --no-restart $APP WEBEDIT_SESSION_SECRET=\"\$(openssl rand -base64 48)\" >/dev/null" \
  "[ -n \"\$(dokku config:get $APP WEBEDIT_TOKEN_KEY)\" ] || dokku config:set --no-restart $APP WEBEDIT_TOKEN_KEY=\"\$(openssl rand -base64 32)\" >/dev/null"
pause "Done? Press Enter"
say "Now the App secret. The command below reads it at a hidden prompt, so it stays"
say "out of shell history and off the screen."
step "On the Dropbox Settings tab, click Show next to App secret and copy it."
on_server \
  "read -rsp 'Dropbox App secret: ' S; echo; dokku config:set --no-restart $APP WEBEDIT_DROPBOX_APP_SECRET=\"\$S\" >/dev/null; unset S"
step "Check the seven WEBEDIT_ keys are all there (names only, no values):"
on_server "dokku config:keys $APP | grep WEBEDIT_"
pause "All seven listed? Press Enter"

stage "Dokku: storage for the token"
say "The encrypted refresh token lives in /data. The image runs as uid 65532"
say "(distroless nonroot), so the host directory must belong to that uid."
on_server \
  "dokku storage:ensure-directory --chown false $APP" \
  "sudo chown 65532:65532 /var/lib/dokku/data/storage/$APP" \
  "sudo chmod 700 /var/lib/dokku/data/storage/$APP" \
  "dokku storage:mount $APP /var/lib/dokku/data/storage/$APP:/data"
note "storage:mount complains if it's already mounted: that's fine on a rerun."
pause "Done? Press Enter"

stage "First deploy"
say "Push this repo to Dokku; it builds the Dockerfile (a few minutes the first time)."
note "Your SSH key must be in Dokku: 'dokku ssh-keys:list' on the server shows it."
on_laptop \
  "git remote get-url dokku 2>/dev/null || git remote add dokku dokku@$DOKKU_HOST:$APP" \
  "git push dokku master"
note "If startup fails, 'dokku logs $APP' names each missing or malformed variable."
pause "Deployed? Press Enter"

stage "HTTPS"
say "The letsencrypt plugin and its email are already set up; enable it for this app."
on_server "dokku letsencrypt:enable $APP"
note "Skip it if 'dokku letsencrypt:list' already shows $APP with a certificate."
pause "Done? Press Enter"

stage "Check it's live, then sign in"
if command -v curl >/dev/null 2>&1; then
  if curl -fsS --max-time 15 "$BASE_URL/api/health" | grep -q '"ok"'; then
    printf '  %s✓ %s/api/health is ok over HTTPS%s\n' "$GREEN" "$BASE_URL" "$RESET"
  else
    warn "$BASE_URL/api/health didn't answer ok. Check 'dokku logs $APP' and 'dokku ps:report $APP'."
    SKIPPED+=("health check over HTTPS: curl $BASE_URL/api/health")
  fi
else
  SKIPPED+=("health check: curl not found; open $BASE_URL/api/health")
fi
say "Sign in with Dropbox as the Owner. Dropbox asks you to allow the app once."
open_url "$BASE_URL/auth/signin"
pause "Signed in and seeing the editor? Press Enter"

stage "Move your files in"
say "The app can only see /Apps/webedit/ (ADR 0003). Dropbox created it when you signed in."
open_url "https://www.dropbox.com/home/Apps"
step "Move the folders and files you want to edit into /Apps/webedit/."
step "Reload the editor: they appear in the file tree."
pause "Done? Press Enter"

finish
note "Every setting lives only in Dokku: 'dokku config:keys $APP' on the server."
note "Rerunning, and rotating the secrets: docs/deploy.md"
printf '\n'
}

run_wizard "$@"; exit
